contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 creditCheck) public payable {
        require(creditCheck == 0);

        uint256 balBefore = address(c).balance;
        bool reverted;

        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && address(c).balance == balBefore);
    }

    receive() external payable {}
}

